INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (102,2,'tea','trà','noun','/tiː/','She likes hot tea.','Cô ấy thích trà nóng.','/doulingo/public/assets/media/images/tea.png','/doulingo/public/assets/media/audio/tea.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (103,2,'coffee','cà phê','noun','/ˈkɒfi/','He drinks coffee at work.','Anh ấy uống cà phê ở chỗ làm.','/doulingo/public/assets/media/images/coffee.png','/doulingo/public/assets/media/audio/coffee.mp3',1);
