INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (201,3,'car','xe hơi','noun','/kɑː/','My uncle has a new car.','Chú tôi có một chiếc xe hơi mới.','/doulingo/public/assets/media/images/car.png','/doulingo/public/assets/media/audio/car.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (202,3,'bus','xe buýt','noun','/bʌs/','I go to school by bus.','Tôi đi học bằng xe buýt.','/doulingo/public/assets/media/images/bus.png','/doulingo/public/assets/media/audio/bus.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (203,3,'train','tàu hỏa','noun','/treɪn/','The train is very fast.','Tàu hỏa chạy rất nhanh.','/doulingo/public/assets/media/images/train.png','/doulingo/public/assets/media/audio/train.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (204,3,'plane','máy bay','noun','/pleɪn/','The plane lands at noon.','Máy bay hạ cánh lúc trưa.','/doulingo/public/assets/media/images/plane.png','/doulingo/public/assets/media/audio/plane.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (205,3,'bike','xe đạp','noun','/baɪk/','He rides a bike to work.','Anh ấy đạp xe đi làm.','/doulingo/public/assets/media/images/bike.png','/doulingo/public/assets/media/audio/bike.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (206,3,'motorbike','xe máy','noun','/ˈməʊtəbaɪk/','Many people ride motorbikes here.','Nhiều người chạy xe máy ở đây.','/doulingo/public/assets/media/images/motorbike.png','/doulingo/public/assets/media/audio/motorbike.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (207,3,'boat','con thuyền','noun','/bəʊt/','The boat crosses the river.','Con thuyền băng qua sông.','/doulingo/public/assets/media/images/boat.png','/doulingo/public/assets/media/audio/boat.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (208,3,'taxi','xe taxi','noun','/ˈtæksi/','Let''s take a taxi.','Chúng ta đi taxi nhé.','/doulingo/public/assets/media/images/taxi.png','/doulingo/public/assets/media/audio/taxi.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (209,3,'truck','xe tải','noun','/trʌk/','The truck carries rice.','Chiếc xe tải chở gạo.','/doulingo/public/assets/media/images/truck.png','/doulingo/public/assets/media/audio/truck.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (210,3,'ship','tàu thủy','noun','/ʃɪp/','The ship is very big.','Con tàu thủy rất lớn.','/doulingo/public/assets/media/images/ship.png','/doulingo/public/assets/media/audio/ship.mp3',1);
INSERT INTO words (id,topic_id,english,vietnamese,part_of_speech,ipa,example,example_translation,image,audio,is_active) VALUES (211,3,'helicopter','trực thăng','noun','/ˈhelɪkɒptə/','A helicopter flies above us.','Trực thăng bay phía trên chúng tôi.','/doulingo/public/assets/media/images/helicopter.png','/doulingo/public/assets/media/audio/helicopter.mp3',1);
